/**
 * Client entry (foundation). Wires the client model (src/client.js), the shell and its panels
 * (src/ui), the venue scene host, the maps and the community panel together.
 * Feature owners do not edit this file: panels plug in through src/ui/panels, scenes through
 * src/scene, rules through src/game.
 *
 * FIRST LOAD. Only the shell, the eager panels and the rules needed to draw the HUD are in the
 * entry chunk. Everything heavy is fetched after the HUD is on screen and usable:
 *   - the 3D scene host with Three.js and every scene module   (loadScene, straight after start)
 *   - the city map (the 3D miniature in src/map3d, or the flat one where WebGL is missing) and
 *     the country map                                          (first time the Map opens, or a trip starts)
 *   - the community panel                                      (after the first connection; if its
 *     chunk does not arrive the status line and the community panel say so, it is retried with
 *     a bounded backoff — src/lazy-load.js — and the panel offers Try again and Reload)
 *   - the lazy panel groups                                    (src/ui/panels/index.js)
 * Until a piece arrives its callers simply skip it (`venue?.…`), and it is given the current
 * state the moment it exists, so nothing depends on load order.
 *
 * WHERE PEOPLE STAND. In a public venue the avatar's place in the scene IS the player's place in
 * the room: the scene host reports it (onMove — at most three times a second, only when it moved),
 * it goes to the community module's moveTo(x, z), the server puts it in the room's `presence`, and
 * what comes back through the module's onMembers is drawn in the scene (other players as figures
 * at their own places) AND is what proximity voice measures. One position, one source. Home is
 * private and reports nothing. Nothing here enables voice: that is the Join voice button alone.
 *
 * TRAVEL IS SHOWN ON THE MAP. Whatever started a trip (the map card, the Ride app, Go to work),
 * the moment the server reports it the Map becomes the screen in front and shows the trip; when
 * the server reports the arrival the map shows it for a moment and then the venue comes up. The
 * rules and the timer stay the server's — see accepted() and src/map3d/trip.js.
 */
import { createClient, CITIES, roomJoinNeeded } from './client.js';
import { createLazyLoader } from './lazy-load.js';
import { createShell } from './ui/shell.js';
import { linkWords } from './ui/link.js';
import { PANELS, sessionGate } from './ui/panels/index.js';
import { S as social, loadPeople, onPeople } from './ui/panels/social-client.js';
import { crowdList, playersHere } from './scene/crowd.js';
import { NPCS } from './game/content/npcs.js';
import { viewLife, VENUES, isDeparting } from './life.js';
import { venueLabel, venueDistrict } from './game/content/venues.js';

const $ = (id) => document.getElementById(id);
let storage; try { storage = window.localStorage; } catch {}
let community = null, pendingRoute = null, connecting = false;
/** Where the other players in this venue room stand, as the room reports it: { [publicId]: { x, z } }. */
let positions = {};
let shell = null, venue = null, cityMap = null, world = null, mapsLoading = null;
/** The connection status line: shown in the top bar's saved indicator and in the More menu. */
let net = { text: 'Connecting…', error: false };

function status(text, error = false) { net = { text, error }; if (shell) render(); }

/** The trip a state is on, as a key ('' when it is not travelling): a different key is a different trip. */
const tripKey = (state) => (isDeparting(state) ? `${state.activeAction.kind}|${state.location}|${state.activeAction.id}|${state.activeAction.duration}` : '');

const client = createClient({
  storage,
  isHidden: () => document.hidden,
  onStatus: status,
  onChange: accepted,
  onSessionExpired() { community?.destroy(); community = null; positions = {}; render(); shell.open(sessionGate().id, { reason: 'expired' }); },
  onNeedName(problem) { shell.open(sessionGate().id, { reason: 'new', problem: problem ?? null }); },
});

/** The player's avatar in every scene: their saved look, seeded by the session's public id (never the cookie). */
const playerLook = () => ({ look: client.state.onboarding?.look, seed: client.session?.id ?? 'you', name: client.state.name || client.identity.name });
const showPlayer = () => { venue?.setPlayer(playerLook()); cityMap?.setPlayer(playerLook()); };

/**
 * The crowd in the scene, from real data only: the server's who-is-here listing for this venue
 * room and the venue's regulars. Called when the state or the listing changes; the host compares
 * the list by value, so an unchanged crowd never draws a frame.
 */
function showCrowd() {
  const state = client.state;
  const npcs = isDeparting(state) ? [] : Object.values(NPCS).filter((npc) => npc.venue === state.location);
  venue?.setCrowd(crowdList({ players: playersHere(social.people, state, client.cityId), npcs, selfId: client.session?.id, positions }));
}
let lastPlot = null, followingCity = false;
onPeople(showCrowd);
// Friends' houses are named on the map (public ids only).
const showFriends = () => cityMap?.setFriends((social.me?.friends || []).map((friend) => friend.id));
onPeople(showFriends);

/** Tell the room where the avatar stands right now (the scene itself reports only while it moves). Public venues only. */
function reportPlace() {
  const at = venue?.position?.();
  if (!at || !community || at.location !== client.state.location || at.location === 'home' || isDeparting(client.state)) return;
  community.moveTo(at.x, at.z);
}
/** The room's member list arrived (or emptied): draw the others where they stand, and make sure the room knows where we do. */
function onMembers({ self, members }) {
  const next = {};
  let listed = false, placed = false;
  for (const member of members) {
    if (member.id === self) { listed = true; placed = Boolean(member.position); continue; }
    if (member.position) next[member.id] = member.position;
  }
  positions = next;
  showCrowd();
  if (listed && !placed) reportPlace();
}

/** The 3D scene: fetched once the HUD is up. A device that cannot draw it still gets the whole game. */
async function loadScene() {
  try {
    const { createVenueWorld } = await import('./venue-world.js');
    venue = createVenueWorld($('venue-scene'), { location: client.state.location, onTag: (tag) => {
      // A name tag opens that person's card: a regular (npc:<id>) or a real player (public id).
      if (tag.kind === 'npc') shell.open('person', { npc: tag.id.replace(/^npc:/, '') });
      else if (tag.kind === 'player') shell.open('person', { player: tag.id });
    },
    // The avatar moved: that is where the player stands in the room (presence, and so proximity voice).
    onMove: (at) => { if (at.location === client.state.location && at.location !== 'home' && !isDeparting(client.state)) community?.moveTo(at.x, at.z); } });
    $('scene-wait')?.remove();
    venue.setState(client.state);
    showPlayer();
    showCrowd();
    venue.resize();
    layoutScene();
    reportPlace();
    // Three.js is here now, so the map's own code is a small download: fetch it ahead, so a first trip shows without a wait.
    // (Nothing is built or drawn until the Map opens.)
    void import('./map3d/index.js').catch(() => {});
  } catch (error) {
    console.error('The scene could not be started:', error);
    const wait = $('scene-wait');
    if (wait) wait.textContent = 'The 3D scene could not be drawn on this device. Everything else still works.';
  }
}

/**
 * The two maps, fetched the first time the Map opens (or at once for a shared ?venue= link).
 * What the Map panel says to the city map before it exists is kept and replayed.
 */
const mapUi = {};
const keepMapUi = (event) => Object.assign(mapUi, event.detail || {});
window.addEventListener('jaw:map-ui', keepMapUi);
function loadMaps() {
  mapsLoading ??= Promise.all([import('./map3d/index.js'), import('./world-map.js')]).then(([cityModule, worldModule]) => {
    world = worldModule.createWorldMap($('map-scene'), {
      onOpenCity: () => showMapLayer('city'),
      onEnterCity: (cityId) => switchCity(cityId),
      // One character travels between cities: an ordinary game action, refused with its reason while the city is not open.
      onTravel: (to, mode) => command('estate.relocate', { to, mode }),
      routes: () => (client.state ? viewLife(client.state, { now: client.state.t, cityId: client.cityId }).estate?.links ?? null : null),
      held: heldCities,
    });
    heldShown = heldCities().join();
    cityMap = cityModule.createCityView($('city-scene'), {
      cityId: client.cityId,
      onSelectVenue: (venueId) => shell.open('map', { destination: venueId }),
      onSelectGov: () => shell.open('state-house'),
      onSelectNeighbour: (player) => shell.open('person', { player: player.id, name: player.name }),
      // The world layer: a local government opens its page, a house its owner's card; the maps fetch only what is in view.
      onSelectLga: (lga) => shell.open('lga', { lga }),
      onSelectHouse: (house) => shell.open('house-card', { house }),
      fetchJson: client.fetchJson,
      // The avatar reached the door: ask the server for the arrival now rather than at its next poll.
      onTripDue: () => { if (client.online) void client.refresh(); },
      onNotice: (text) => shell.toast(text),
    });
    window.removeEventListener('jaw:map-ui', keepMapUi);
    world.setCity(client.cityId);
    cityMap.setPlayer(playerLook());
    showFriends();
    cityMap.setState(client.state);
    render();
    if (Object.keys(mapUi).length) window.dispatchEvent(new CustomEvent('jaw:map-ui', { detail: mapUi }));
    refreshScene();
  }).catch((error) => { mapsLoading = null; console.error('The map could not be loaded:', error); shell.toast('The map could not be loaded. Check your connection and open it again.', 'error'); });
  return mapsLoading;
}

/** Open the Map on the city map ('city') or the country map ('world'). The maps are told first, so the right one is in front when the shell draws. */
function showMapLayer(layer) {
  window.dispatchEvent(new CustomEvent('jaw:map-ui', { detail: { layer } }));
  shell.open('map', { layer });
}

const dialog = $('life-dialog');
shell = createShell({
  root: $('life-overlay'), dialog, dialogContent: $('life-dialog-content'), panels: PANELS,
  host: { command, fetchJson: client.fetchJson, newId: client.newId, goTo, toggleCommunity, menu, onRender: () => layoutScene(), redrawScene: () => { if (shell.mode !== 'map') venue?.update(); }, onMode(mode) {
    // A trip is watched on the map: while one is running there is no venue to stand in, so the venue screen
    // (and the shell's old full-panel travel view with it) is never what is in front.
    if (mode === 'venue' && tripKey(client.state)) { shell.setMode('map'); return; }
    if (mode === 'map') loadMaps();
    render(); refreshScene();
  } },
});

const clockFormat = new Intl.DateTimeFormat('en-NG', { timeZone: 'Africa/Lagos', weekday: 'short', day: 'numeric', hour: 'numeric', minute: '2-digit', hour12: true });
function buildView() {
  const now = client.serverNow(), cityId = client.cityId;
  return {
    ...viewLife(client.state, { now, cityId }),
    cityId, city: CITIES[cityId], connected: client.online, link: client.link, session: client.session, net, storage: client.storage,
    // The life's own name (the server keeps it equal to the session nickname), so a rename shows as soon as the next state arrives.
    name: client.state.name || client.identity.name, now,
    clock: clockFormat.format(new Date(now)).replace(',', ' ·'),
    venues: Object.values(VENUES).map((item) => ({ id: item.id, label: venueLabel(item.id, cityId), district: venueDistrict(item.id, cityId), icon: item.icon, description: item.description })),
  };
}

function render() {
  const state = client.state, mapOpen = shell.mode === 'map';
  document.body.classList.toggle('map-open', mapOpen);
  if (state.location === 'home') $('community-panel').hidden = true;
  const worldLayer = cityMap ? cityMap.ready === false : false;
  $('venue-scene').hidden = mapOpen;
  $('map-scene').hidden = !mapOpen || !worldLayer;
  $('city-scene').hidden = !mapOpen || worldLayer;
  shell.render(state, buildView());
  // The country map shows which cities this player holds: redrawn when that list changes (a session arrived, a city was entered).
  if (world && heldCities().join() !== heldShown) { heldShown = heldCities().join(); world.refresh(); }
  // A trip between cities is drawn on the world map, where the server's timer says it is.
  world?.setState?.(state);
  // Told after the shell has drawn, so the map measures the panel it shares the screen with. Hidden, it draws nothing.
  cityMap?.setShown(mapOpen && !worldLayer);
}
/** Tell the scene how much of the screen the HUD covers, so it draws itself in the free part. Measured after each shell render (host.onRender). */
function layoutScene() {
  if (!venue || !shell || shell.mode === 'map') return;
  const overlay = $('life-overlay'), box = (selector) => overlay.querySelector(selector)?.getBoundingClientRect();
  const stack = box('.life-bottom'), quick = box('.life-quick'), bar = box('.life-status'), page = overlay.getBoundingClientRect();
  const phone = page.width <= 720;
  // On a phone the rows under the top bar (needs, alerts, the goal line) are the HUD's: the scene's one-time hint sits under the last of them.
  const rows = phone ? Math.max(0, ...['.life-quick', '.life-alerts', '.life-goal'].map((selector) => { const row = box(selector); return row && row.height ? row.bottom : 0; })) : 0;
  venue.setInsets({ top: ((phone ? quick?.bottom : bar?.bottom) || bar?.bottom || page.top) - page.top, bottom: stack?.height ? page.bottom - stack.top : 0, hint: rows ? rows - page.top : 0 });
}
function refreshScene() { if (shell.mode === 'map') { world?.resize(); cityMap?.resize(); } else venue?.resize(); }

/**
 * The cities this player has a life in, so the country map can offer a "coming soon" city only to
 * someone who already lives there. The server says so in the session response (session.cities),
 * which makes it true on every device. Only a server that does not report it yet (an older host)
 * falls back to what this browser remembers.
 */
const HELD_KEY = 'joinallworld-cities';
function rememberedCities() { try { const list = JSON.parse(storage.getItem(HELD_KEY) || '[]'); return Array.isArray(list) ? list.filter((id) => typeof id === 'string') : []; } catch { return []; } }
function heldCities() { const held = client.session?.cities; return Array.isArray(held) ? held.filter((id) => typeof id === 'string') : rememberedCities(); }
function noteCity(id) { try { const list = rememberedCities(); if (!list.includes(id)) storage.setItem(HELD_KEY, JSON.stringify([...list, id])); } catch { /* remembered for this visit only */ } }
let heldShown = '';

let shownTrip = '';
function showVenue() {
  if (shell.mode === 'venue') return;
  shell.setMode('venue');
  // The venue comes up with a short fade rather than a cut.
  const scene = $('venue-scene');
  scene.classList.remove('is-arriving'); void scene.offsetWidth; scene.classList.add('is-arriving');
}

/** Called after every accepted server state. */
function accepted(state, previous) {
  const moved = previous.location !== state.location;
  noteCity(client.cityId);
  // A trip started — from the map card, the Ride app, Go to work, anywhere: the map shows it. Once per trip, so a
  // player who then opens another screen (Buy, a Phone app) is not pulled back; leaving that screen returns to the map.
  const trip = tripKey(state);
  if (trip && trip !== shownTrip && shell.mode !== 'map') shell.setMode('map');
  shownTrip = trip;
  if (moved) {
    venue?.setLocation(state.location);
    // Arrived while watching the trip: the map shows the arrival for a moment, then the venue comes up.
    if (shell.mode === 'map' && cityMap && isDeparting(previous)) { cityMap.setState(state); cityMap.arrive(showVenue); }
    else if (shell.mode !== 'venue') shell.setMode('venue');
    if (pendingRoute && pendingRoute.venue !== state.location) pendingRoute = null; // went somewhere else instead
  }
  // Arrival, or a cancelled trip: restore room membership. Join only — voice stays off until the player asks.
  if (roomJoinNeeded(previous, state)) community?.join(client.cityId, state.location);
  venue?.setState(state);
  showPlayer();
  showCrowd();
  // One character: the life has arrived in another city. The server files it under that city (asked for here, so it is
  // done before the new city's life is requested), then the game follows it there.
  if (state?.estate?.city && state.estate.city !== client.cityId && !followingCity) {
    followingCity = true;
    const to = state.estate.city;
    client.fetchJson(`/api/world/me?city=${client.cityId}`).catch(() => {}).finally(() => { followingCity = false; switchCity(to); });
  }
  // The server has set a plot aside for this life (or moved it): tell the maps and, decoupled, analytics. No address, no name.
  const plotKey = state?.estate?.plot ? `${state.estate.plot.lga}/${state.estate.plot.estate}/${state.estate.plot.plot}` : '';
  if (plotKey !== lastPlot) { if (plotKey && lastPlot !== null) { window.dispatchEvent(new CustomEvent('jaw:track', { detail: { name: 'house_allocated', props: {} } })); window.dispatchEvent(new CustomEvent('jaw:world-changed')); } lastPlot = plotKey; }
  cityMap?.setState(state);
  render();
  // Arrived somewhere (or a trip ended): read who is here once; later changes are pushed by the server.
  if (roomJoinNeeded(previous, state) && client.online) void loadPeople();
  if (pendingRoute && !state.activeAction) {
    const route = pendingRoute;
    if (state.location === route.venue) { pendingRoute = null; if (route.spot) { shell.setExpanded(true); void command('spot', { id: route.spot }); } }
    else if (!client.online) pendingRoute = null;
  }
}

async function command(type, payload) {
  if (type === 'cancel') pendingRoute = null;
  const result = await client.command(type, payload);
  if (!result.ok && result.reason && result.code !== 'busy') shell.toast(result.reason, 'error');
  if (!result.ok && type === 'travel') pendingRoute = null;
  return result;
}

/**
 * Go to a venue and stand at a spot there. Already there: select the spot. Elsewhere: open the
 * Map travel card for the venue (mode tiles, Danfo selected) — a trip is never started on the
 * player's behalf — and remember the spot for when they arrive.
 */
async function goTo(venueId, spotId) {
  if (client.state.location === venueId) {
    if (shell.mode !== 'venue') shell.setMode('venue');
    if (spotId) { shell.setExpanded(true); await command('spot', { id: spotId }); render(); }
    return;
  }
  pendingRoute = { venue: venueId, spot: spotId };
  shell.open('map', { destination: venueId });
}

/**
 * The community panel's code, fetched after the first connection. The chunk can fail to arrive (a
 * dropped connection, a deploy in between): the loader then retries by itself after 1, 2, 4, 8 and
 * 16 seconds and stops. The status line always says which of these is true — it never reads
 * "connecting" for something that is not being tried.
 */
const communityCode = createLazyLoader(() => Promise.all([import('./community.js'), import('./community.css')]).then(([module]) => module), {
  onState(state) {
    if (state.status === 'retrying') status(`Community did not load · retrying in ${Math.round(state.retryInMs / 1000)} s (attempt ${state.attempt + 1} of ${state.attempts})`, true);
    else if (state.status === 'failed') status('Community is unavailable · it did not load. Open Community to retry', true);
    // A retry that succeeded by itself: bring the panel up now, without waiting for the player.
    else if (state.status === 'ready') void startCommunity();
    showCommunityRecovery();
  },
});
/**
 * What the community panel shows while its code is not here: what happened, what happens next
 * (the same bounded retries as the status line — nothing else requests the chunk), and the two
 * things the player can do. "Reload and retry" comes first: a browser can keep a failed module
 * download for the life of the page (Chromium does — the file is reachable again and the import
 * still fails), and then no in-page retry can succeed. A reload keeps the saved identity and asks
 * for no microphone access. "Try again" asks the loader at once, for browsers that do fetch again.
 */
function showCommunityRecovery(startProblem = null) {
  if (community) return;
  const content = $('community-content'), load = communityCode.state;
  const waiting = load.status === 'loading', down = load.status === 'retrying' || load.status === 'failed' || Boolean(startProblem);
  if (!down && !(waiting && content.querySelector('[data-community-recovery]'))) return;
  const next = waiting ? 'Trying again now…'
    : load.status === 'retrying' ? `Trying again by itself in ${Math.round(load.retryInMs / 1000)} s (attempt ${load.attempt + 1} of ${load.attempts}).`
      : load.status === 'failed' ? 'It was tried several times and is no longer being retried. Reload to try again.' : 'Its code loaded but it could not start.';
  content.innerHTML = `<section data-community-recovery aria-label="Community unavailable"><h2>Community could not load</h2><p>Your saved city life is still available. Check your connection, then try community again.</p><p role="status">${next}</p><p><button type="button" class="ui-button is-primary" data-community-reload>Reload and retry</button> <button type="button" class="ui-button" data-community-retry${waiting ? ' disabled' : ''}>Try again</button></p></section>`;
  content.querySelector('[data-community-retry]').onclick = () => { if (!client.online) shell.toast(notConnected('open the community'), 'error'); else void startCommunity(); };
  content.querySelector('[data-community-reload]').onclick = () => window.location.reload();
}
/** Why something cannot be done right now, in the words of the real connection state — "offline" only when this device has no network. */
const notConnected = (what) => linkWords(client.link)?.cannot(what) || `You are not connected yet, so you cannot ${what}. Try again in a moment.`;
let startingCommunity = false;
/** Create the community panel once its code is here and the client is connected. Safe to call any number of times. */
async function startCommunity() {
  if (community || startingCommunity || !client.online) return;
  startingCommunity = true;
  try {
    const module = await communityCode.load();
    if (!module || community || !client.online) return;
    community = await module.createCommunity($('community-content'), { cityId: client.cityId, venueId: client.state.location,
      onMembers,
      // The panel's Walk buttons walk the avatar; its new place comes back through onMove like any other step.
      onStep: (dx, dz) => venue?.walkBy?.(dx, dz) === true,
      onStatus: (s) => { if (s.status === 'offline') status('Community disconnected · reconnect in panel', true); else if (s.connected) status('Connected · progress saved'); } });
    watchChatRefusals($('community-content'));
    render();
  } catch (error) {
    console.error('The community panel could not be started:', error);
    status('Community is unavailable · it could not start. Open Community to retry', true);
    showCommunityRecovery(error);
  } finally { startingCommunity = false; }
}

function toggleCommunity(force) {
  if (client.state.location === 'home') { shell.toast('Your home is private. Visit a public venue to meet people.'); return; }
  if (!community) {
    if (!client.online) { shell.toast(notConnected('open the community'), 'error'); return; }
    // Not loaded: the panel itself says so and offers the retry (showCommunityRecovery). While the
    // first attempt is still in flight there is nothing to show yet, only to wait for.
    if (!$('community-content').querySelector('[data-community-recovery]')) {
      shell.toast('Community is still loading. Try again in a moment.');
      void startCommunity(); // starts at once, or joins the attempt already in flight
      return;
    }
  }
  $('community-panel').hidden = typeof force === 'boolean' ? !force : !$('community-panel').hidden;
}

/**
 * A venue chat line the server refused (blocked wording, or the player is muted). The community
 * panel does not pass the refusal's code to onStatus; all it exposes is its own status line
 * (`.community-feedback`), where it prints the sentence the server sent, and "Not sent" on the line
 * itself. That sentence is repeated as a toast so it is seen wherever the panel is scrolled to.
 * Event-driven (a MutationObserver on that one element): nothing runs while the game is idle.
 */
let chatWatch = null;
function watchChatRefusals(container) {
  chatWatch?.disconnect();
  const line = container.querySelector('.community-feedback');
  if (!line || typeof MutationObserver !== 'function') return;
  chatWatch = new MutationObserver(() => {
    const text = line.textContent.trim();
    const refused = [...container.querySelectorAll('.community-messages li small')].some((node) => node.textContent === 'Not sent');
    if (text && refused) shell.toast(text, 'error');
  });
  chatWatch.observe(line, { childList: true, characterData: true, subtree: true });
}

async function connect(createNew = false) {
  if (connecting) return;
  connecting = true;
  try {
    if (createNew) { community?.destroy(); community = null; positions = {}; }
    const ok = await client.connect(createNew);
    render();
    // Not awaited: a slow or failing community chunk must not hold up the game or block a later Reconnect.
    if (ok) void startCommunity();
  } finally { connecting = false; }
}

async function switchCity(id) {
  const result = await client.switchCity(id);
  if (!result.ok) { if (result.reason) shell.toast(result.reason, 'error'); return; }
  noteCity(id);
  world?.setCity(id); cityMap?.setCity(id);
  community?.join(id, client.state.location);
  venue?.setLocation(client.state.location);
  shell.setMode('venue');
  shell.open('city', { city: id });
}

/** Entries of the shell's More menu and the top bar's Reconnect. */
function menu(id) {
  if (id === 'reconnect') connect();
  // The country map: the city you are in, and the cities that are coming soon.
  else if (id === 'city') showMapLayer('world');
}

window.addEventListener('jaw:start-life', (event) => { if (event.detail?.name) client.identity.name = event.detail.name; connect(true); });
window.addEventListener('jaw:reconnect', () => connect());
window.addEventListener('jaw:switch-city', (event) => switchCity(event.detail.city));
$('close-life-dialog').onclick = () => shell.close();
$('community-close').onclick = () => toggleCommunity(false);
window.addEventListener('resize', refreshScene);
// The device got its network back: try the connection once, by itself (an event, not a timer).
window.addEventListener('online', () => { if (!client.online && (client.link === 'offline' || client.link === 'unreachable')) connect(); });
window.addEventListener('pagehide', () => { community?.destroy(); client.stop(); });
document.addEventListener('visibilitychange', () => { if (document.hidden) client.stop(); else if (client.online) client.refresh(); });

if (new URLSearchParams(location.search).has('diagnostics')) {
  const panel = document.createElement('aside');
  panel.style.cssText = 'position:fixed;left:10px;bottom:90px;z-index:60;background:white;color:black;padding:8px;max-width:340px;font:12px monospace';
  const button = document.createElement('button'); button.textContent = 'Read renderer diagnostics';
  const output = document.createElement('pre'); output.id = 'render-diagnostics';
  button.onclick = () => { output.textContent = JSON.stringify({ ...(venue ? venue.diagnostics() : { renderCount: 0, scene: 'not loaded yet' }), map: cityMap ? cityMap.diagnostics() : 'not loaded yet', visibility: document.visibilityState, lazyPanelsWaiting: PANELS.filter((item) => item.pending).map((item) => item.id) }, null, 2); };
  // For the same diagnostics from a test harness: the map, the client and the shell mode.
  window.__jaw = { get map() { return cityMap; }, get client() { return client; }, get mode() { return shell.mode; }, get venue() { return venue; } };
  panel.append(button, output); document.body.append(panel);
}

render();
connect();
// The scene (Three.js and every scene module) starts downloading only now, with the HUD already on screen and usable.
setTimeout(loadScene, 0);
if (new URLSearchParams(location.search).has('venue')) loadMaps();
